    for (const unresolved of ["| OBSERVED |", "| PARTIAL |", "| GAP |", "| UNKNOWN |", "| TODO |"]) {
      expect(matrix).not.toContain(unresolved);
    }
    expect(matrix).toContain("Known implementation gaps: **0**");
  });

