#!/usr/bin/env node

import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, unlinkSync, writeFileSync } from "node:fs";
import { checkSourceManifest, SOURCE_MANIFEST_PATH } from "./source-manifest.mjs";

const TRANSPORT_PATHS = Array.from(
  { length: 14 },
  (_, index) => `release/oauth-bundle-${index + 1}.json`,
);
const DIRECT_SOURCE_PATHS = new Set([
  "package.json",
  "package-lock.json",
  "release/oauth-unpack.mjs",
  "vercel.json",
]);
const TRANSPORT_PATH_SET = new Set(TRANSPORT_PATHS);

function gitBlobSha(content) {
  const body = Buffer.from(content, "utf8");
  return createHash("sha1")
    .update(`blob ${body.length}\0`, "utf8")
    .update(body)
    .digest("hex");
}

function trackedEntries() {
  const output = execFileSync("git", ["ls-files", "-s"], { encoding: "utf8" });
  return output
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const tab = line.indexOf("\t");
      if (tab < 0) throw new Error(`Invalid git ls-files entry: ${line}`);
      const [mode, sha, stage] = line.slice(0, tab).trim().split(/\s+/u);
      const path = line.slice(tab + 1);
      if (!mode || !sha || stage !== "0") {
        throw new Error(`Unsupported git index entry: ${line}`);
      }
      return { path, sha };
    })
    .sort((a, b) => a.path.localeCompare(b.path));
}

for (const path of TRANSPORT_PATHS) {
  if (existsSync(path)) unlinkSync(path);
}

const certification = checkSourceManifest();
const entries = trackedEntries();

for (const { path } of entries) {
  if (TRANSPORT_PATH_SET.has(path)) {
    throw new Error(`OAuth transport files must never be tracked in the certified source tree: ${path}`);
  }
}

const sourceFiles = [];
for (const { path, sha } of entries) {
  if (path === SOURCE_MANIFEST_PATH || DIRECT_SOURCE_PATHS.has(path)) continue;
  const data = readFileSync(path, "utf8");
  const actualSha = gitBlobSha(data);
  if (actualSha !== sha) {
    throw new Error(
      `OAuth packer requires UTF-8 source whose Git blob matches the index: ${path}`,
    );
  }
  sourceFiles.push({
    path,
    blobSha: sha,
    data,
    bytes: Buffer.byteLength(data, "utf8"),
  });
}

const bootstrap = [];
for (const path of DIRECT_SOURCE_PATHS) {
  const entry = entries.find((item) => item.path === path);
  if (!entry) throw new Error(`OAuth packer missing required direct source file: ${path}`);
  const data = readFileSync(path, "utf8");
  if (gitBlobSha(data) !== entry.sha) {
    throw new Error(`OAuth packer direct file differs from the Git index: ${path}`);
  }
  bootstrap.push({
    path,
    blobSha: entry.sha,
    ...(path === "vercel.json" ? { data } : {}),
  });
}

const bins = Array.from({ length: TRANSPORT_PATHS.length }, () => ({
  bytes: 0,
  files: [],
}));

for (const file of [...sourceFiles].sort((a, b) => b.bytes - a.bytes)) {
  bins.sort((a, b) => a.bytes - b.bytes);
  bins[0].files.push(file);
  bins[0].bytes += file.bytes;
}

bins.forEach((bin, index) => {
  const payload = {
    schemaVersion: 3,
    sourceHash: certification.sourceHash,
    bootstrap,
    files: bin.files.map(({ path, blobSha, data }) => ({ path, blobSha, data })),
  };
  writeFileSync(TRANSPORT_PATHS[index], JSON.stringify(payload), "utf8");
});

const totalBytes = bins.reduce((sum, bin) => sum + bin.bytes, 0);
console.log(
  `OAuth transport: packed ${sourceFiles.length} tracked files (${totalBytes} UTF-8 bytes) into ${TRANSPORT_PATHS.length} certified parts for ${certification.releaseId}.`,
);

import { describe, expect, it } from "vitest";
import {
  canonicalizeArtifact,
  createArtifactReceipt,
  inspectArtifactHygiene,
  sha256Hex,
  verifyArtifactReceipt,
} from "../src/lib/artifacts/provenance";

describe("artifact provenance receipts", () => {
  it("canonicalizes JSON key ordering deterministically", async () => {
    const a = canonicalizeArtifact('{"b":2,"a":{"z":3,"y":1}}', "json");
    const b = canonicalizeArtifact(' { "a": { "y": 1, "z": 3 }, "b": 2 } ', "json");
    expect(a.text).toBe(b.text);
    expect(await sha256Hex(a.text)).toBe(await sha256Hex(b.text));
    expect(a.canonicalization).toBe("stable-json-v1");
  });

  it("creates a self-hashed receipt and verifies the artifact locally", async () => {
    const artifact = "# Skill\n\nName: verifier\nPurpose: Verify supplied evidence.";
    const receipt = await createArtifactReceipt(artifact, {
      kind: "agent-skill",
      artifactName: "verifier",
      artifactVersion: "1.0.0",
      previousArtifactHash: "a".repeat(64),
      createdAt: "2026-09-18T00:00:00.000Z",
    });
    expect(receipt.artifactHash).toMatch(/^[a-f0-9]{64}$/u);
    expect(receipt.receiptHash).toMatch(/^[a-f0-9]{64}$/u);
    expect(receipt.previousArtifactHash).toBe("a".repeat(64));
    const verified = await verifyArtifactReceipt(artifact, receipt);
    expect(verified.artifactMatches).toBe(true);
    expect(verified.receiptIntegrity).toBe(true);
    expect(verified.chainLinkWellFormed).toBe(true);
  });

  it("detects artifact changes without trusting receipt metadata", async () => {
    const receipt = await createArtifactReceipt("name: safe\npurpose: test", { kind: "agent-skill", createdAt: "2026-09-18T00:00:00.000Z" });
    const verified = await verifyArtifactReceipt("name: changed\npurpose: test", receipt);
    expect(verified.artifactMatches).toBe(false);
    expect(verified.receiptIntegrity).toBe(true);
  });

  it("detects receipt tampering", async () => {
    const receipt = await createArtifactReceipt("plain artifact", { kind: "generic", createdAt: "2026-09-18T00:00:00.000Z" });
    const altered = { ...receipt, artifactVersion: "tampered" };
    const verified = await verifyArtifactReceipt("plain artifact", altered);
    expect(verified.receiptIntegrity).toBe(false);
  });

  it("flags credential-like material without echoing the secret", () => {
    const findings = inspectArtifactHygiene("token=sk-123456789012345678901234567890", "generic");
    const secret = findings.find((item) => item.code === "credential_like_material");
    expect(secret?.severity).toBe("blocked");
    expect(secret?.message).not.toContain("sk-123456789012345678901234567890");
  });

  it("rejects malformed version-chain hashes", async () => {
    await expect(createArtifactReceipt("artifact", { kind: "generic", previousArtifactHash: "not-a-hash" })).rejects.toThrow(/64-character SHA-256/u);
  });
});

import type { TransformMetrics } from "./types";

export function words(text: string) {
  return text.toLocaleLowerCase().match(/[\p{L}\p{N}]+(?:['’][\p{L}\p{N}]+)*/gu) ?? [];
}

export function longestSharedWordRun(source: string, output: string) {
  const a = words(source);
  const b = words(output);
  if (!a.length || !b.length) return 0;

  let previous = new Uint32Array(b.length + 1);
  let longest = 0;
  for (let i = 1; i <= a.length; i += 1) {
    const current = new Uint32Array(b.length + 1);
    for (let j = 1; j <= b.length; j += 1) {
      if (a[i - 1] === b[j - 1]) {
        current[j] = previous[j - 1] + 1;
        longest = Math.max(longest, current[j]);
      }
    }
    previous = current;
  }
  return longest;
}

function ngrams(tokens: string[], size: number) {
  const set = new Set<string>();
  for (let i = 0; i <= tokens.length - size; i += 1) set.add(tokens.slice(i, i + size).join(" "));
  return set;
}

export function trigramOverlap(source: string, output: string) {
  const sourceSet = ngrams(words(source), 3);
  const outputSet = ngrams(words(output), 3);
  if (!sourceSet.size && !outputSet.size) return 1;
  if (!sourceSet.size || !outputSet.size) return 0;

  let intersection = 0;
  for (const gram of sourceSet) if (outputSet.has(gram)) intersection += 1;
  const union = sourceSet.size + outputSet.size - intersection;
  return union ? intersection / union : 0;
}

export function lexicalReplacementPercent(source: string, output: string) {
  const sourceWords = words(source);
  if (!sourceWords.length) return 0;
  const outputCounts = new Map<string, number>();
  for (const token of words(output)) outputCounts.set(token, (outputCounts.get(token) ?? 0) + 1);
  let shared = 0;
  for (const token of sourceWords) {
    const remaining = outputCounts.get(token) ?? 0;
    if (remaining > 0) { shared += 1; outputCounts.set(token, remaining - 1); }
  }
  return Math.max(0, Math.min(100, (1 - shared / sourceWords.length) * 100));
}

export function buildTransformMetrics(source: string, output: string, protectedTotal: number, protectedPreserved: number): TransformMetrics {
  const sourceWords = words(source).length;
  const outputWords = words(output).length;
  const lengthRatio = sourceWords ? outputWords / sourceWords : 1;
  return {
    sourceWords,
    outputWords,
    lengthRatio,
    retainedPercent: lengthRatio * 100,
    wordingReplacedPercent: lexicalReplacementPercent(source, output),
    protectedTotal,
    protectedPreserved,
    longestSharedWordRun: longestSharedWordRun(source, output),
    trigramOverlap: trigramOverlap(source, output),
    unprotectedLongestSharedWordRun: 0,
  };
}

