import { createHash } from "node:crypto";

const SENSITIVE_KEY = /(authorization|cookie|secret|token|password|signature|raw|body|content|text|manifest|ip)$/iu;

type MetaValue = string | number | boolean | null | undefined;
export type OperationalMetadata = Record<string, MetaValue>;

export function hashIdentifier(value: string, saltOverride?: string) {
  const salt = saltOverride || process.env.RATE_LIMIT_HASH_SALT || process.env.VERCEL_OIDC_TOKEN || process.env.VERCEL_DEPLOYMENT_ID || "local-development-only";
  return createHash("sha256").update(`${salt}:${value}`).digest("hex").slice(0, 32);
}

export function logEvent(event: string, metadata: OperationalMetadata = {}) {
  const safe: Record<string, MetaValue | "[redacted]"> = {};
  for (const [key, value] of Object.entries(metadata)) {
    if (SENSITIVE_KEY.test(key)) safe[key] = "[redacted]";
    else if (typeof value === "string") safe[key] = value.slice(0, 200);
    else safe[key] = value;
  }
  console.info(JSON.stringify({ timestamp: new Date().toISOString(), event, ...safe }));
}

export function requestSubjectKey(request: Request, userId?: string | null) {
  const requestSalt = process.env.RATE_LIMIT_HASH_SALT || request.headers.get("x-vercel-oidc-token") || process.env.VERCEL_OIDC_TOKEN || process.env.VERCEL_DEPLOYMENT_ID || "local-development-only";
  if (userId) return `user:${hashIdentifier(userId, requestSalt)}`;
  const forwarded = request.headers.get("x-forwarded-for")?.split(",", 1)[0]?.trim();
  const real = request.headers.get("x-real-ip")?.trim();
  return `ip:${hashIdentifier(forwarded || real || "unknown", requestSalt)}`;
}

export const ascii = (bytes: Uint8Array, start = 0, end = bytes.length) =>
  String.fromCharCode(...bytes.subarray(start, end));

export const latin1 = (bytes: Uint8Array) => {
  let output = "";
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    output += String.fromCharCode(...bytes.subarray(i, Math.min(bytes.length, i + chunk)));
  }
  return output;
};

export function readUint32BE(bytes: Uint8Array, offset: number): number {
  return (
    ((bytes[offset] ?? 0) << 24) |
    ((bytes[offset + 1] ?? 0) << 16) |
    ((bytes[offset + 2] ?? 0) << 8) |
    (bytes[offset + 3] ?? 0)
  ) >>> 0;
}

export function readUint32LE(bytes: Uint8Array, offset: number): number {
  return (
    (bytes[offset] ?? 0) |
    ((bytes[offset + 1] ?? 0) << 8) |
    ((bytes[offset + 2] ?? 0) << 16) |
    ((bytes[offset + 3] ?? 0) << 24)
  ) >>> 0;
}

export function writeUint32LE(bytes: Uint8Array, offset: number, value: number) {
  bytes[offset] = value & 0xff;
  bytes[offset + 1] = (value >>> 8) & 0xff;
  bytes[offset + 2] = (value >>> 16) & 0xff;
  bytes[offset + 3] = (value >>> 24) & 0xff;
}

export function concatBytes(parts: Uint8Array[]): Uint8Array {
  const total = parts.reduce((sum, part) => sum + part.length, 0);
  const output = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    output.set(part, offset);
    offset += part.length;
  }
  return output;
}

export const startsWithAscii = (bytes: Uint8Array, value: string) =>
  ascii(bytes, 0, value.length) === value;

